def guide_for(node_id: str, level: str | None) -> dict | None:
    if node_id not in GUIDES:
        return None
    outcome, steps, expected, troubleshooting = GUIDES[node_id]
    if level in {"PRACTICED", "EXPERIENCED"} and node_id not in {"M01", "M02"}:
        # Keep mission-specific operations, including M11 reproduction and M12 explanation.
        approach = "기본 뼈대에서 빠진 동작을 직접 구현하세요." if level == "PRACTICED" else "최소 시작 코드와 아래 실행 계약을 읽고 직접 구현하세요."
        steps = [approach, *steps]
    return {"outcome": outcome, "steps": steps, "expected": expected, "troubleshooting": troubleshooting}
